mapper.select:
SELECT i.id, i.family_id, i.name, IFNULL(i.aliases,'') AS aliases, IFNULL(i.position,'') AS position, IFNULL(i.image_url,'') AS image_url, IFNULL(i.type,'OTHER') AS type, i.quantity, IFNULL(i.unit,'') AS unit, IFNULL(i.note,'') AS note, i.rel_x, i.rel_y, i.room_id AS item_room_id, i.created_by, i.created_at, i.updated_at, r.id AS room_id, r.house_id AS house_id, r.name AS room_name, f.id AS furniture_id, f.name AS furniture_name, h.name AS house_name FROM family_item i LEFT JOIN family_furniture f ON i.furniture_id = f.id LEFT JOIN family_room r ON f.room_id = r.id LEFT JOIN family_house h ON r.house_id = h.id WHERE i.family_id = #{familyId}
AND i.type = #{type}
AND r.id = #{roomId}
AND f.id = #{furnitureId}
AND (i.name LIKE CONCAT('%', #{keyword}, '%') OR i.aliases LIKE CONCAT('%', #{keyword}, '%') OR i.position LIKE CONCAT('%', #{keyword}, '%') OR f.name LIKE CONCAT('%', #{keyword}, '%') OR r.name LIKE CONCAT('%', #{keyword}, '%') OR h.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY h.sort_order, h.id, r.floor, r.sort_order, r.id, f.id, i.id
